package cn.zhuatech.iwms.deep;import cn.zhuatech.iwms.common.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.time.*;
@RestController @RequestMapping("/api/facility-ops") public class DeepDomainController{private final DeepDomainService s;public DeepDomainController(DeepDomainService s){this.s=s;}@GetMapping("/dashboard")ApiResponse<?> dashboard(@RequestParam String organizationCode){return ApiResponse.ok(s.dashboard(organizationCode));}@PostMapping("/assets")ApiResponse<?> asset(@Valid @RequestBody DeepDomainService.AssetRequest r){return ApiResponse.ok(s.createAsset(r));}@PostMapping("/assets/{id}/plans")ApiResponse<?> plan(@PathVariable Long id,@Valid @RequestBody DeepDomainService.PlanRequest r){return ApiResponse.ok(s.createPlan(id,r));}@PostMapping("/plans/{id}/work-orders")ApiResponse<?> generate(@PathVariable Long id,@Valid @RequestBody DeepDomainService.GenerateRequest r){return ApiResponse.ok(s.generate(id,r));}@PostMapping("/work-orders/{id}/assign")ApiResponse<?> assign(@PathVariable Long id,@Valid @RequestBody DeepDomainService.AssignRequest r){return ApiResponse.ok(s.assign(id,r));}@PostMapping("/work-orders/{id}/start")ApiResponse<?> start(@PathVariable Long id){return ApiResponse.ok(s.start(id));}@PostMapping("/work-orders/{id}/complete")ApiResponse<?> complete(@PathVariable Long id,@Valid @RequestBody DeepDomainService.CompleteRequest r){return ApiResponse.ok(s.complete(id,r));}@PostMapping("/service-requests")ApiResponse<?> request(@Valid @RequestBody DeepDomainService.ServiceRequestInput r){return ApiResponse.ok(s.serviceRequest(r));}@PostMapping("/sla/escalate")ApiResponse<?> escalate(@RequestParam String organizationCode,@RequestParam LocalDateTime asOf){return ApiResponse.ok(s.escalate(organizationCode,asOf));}}
